from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from rest_framework.exceptions import PermissionDenied
from django.utils.dateparse import parse_datetime
from .models import FinancialStatement
from .serializers import FinancialStatementSerializer

class HistoricalFinancialSnapshotView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, statement_id):
        as_of_param = request.query_params.get('as_of')
        if not as_of_param:
            return Response({'error': 'as_of timestamp required'}, status=status.HTTP_400_BAD_REQUEST)

        dt = parse_datetime(as_of_param)
        if not dt:
            return Response({'error': 'Invalid datetime format'}, status=status.HTTP_400_BAD_REQUEST)

        try:
            snapshot = FinancialStatement.history.as_of(dt).get(id=statement_id)
        except FinancialStatement.DoesNotExist:
            return Response({'error': 'Historical record not found'}, status=status.HTTP_404_NOT_FOUND)

        if snapshot.company != request.user.company:
            raise PermissionDenied("You do not have permission to view statements for this company.")

        serializer = FinancialStatementSerializer(snapshot)
        return Response(serializer.data)
